import { Component, type ErrorInfo, type ReactNode } from 'react'

import { ErrorState } from './GameUI'

export interface RootErrorBoundaryProps {
  children: ReactNode
  /** Overridable so tests can assert without navigating the jsdom window. */
  onReload?: () => void
}

interface RootErrorBoundaryState {
  error: Error | null
}

function reloadDocument(): void {
  window.location.reload()
}

/**
 * Last line of defence around the whole tree.
 *
 * The scene already guards itself — SceneErrorBoundary inside the Canvas and
 * AssetBoundary around individual models — but anything thrown outside those,
 * including a Suspense child that rethrows, would otherwise unmount the root
 * and leave a blank page with no way back.
 */
export class RootErrorBoundary extends Component<
  RootErrorBoundaryProps,
  RootErrorBoundaryState
> {
  state: RootErrorBoundaryState = { error: null }

  static getDerivedStateFromError(error: unknown): RootErrorBoundaryState {
    return {
      error: error instanceof Error ? error : new Error(String(error)),
    }
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('BODA failed at the root.', error, info.componentStack)
  }

  render() {
    const { error } = this.state
    if (!error) return this.props.children

    // A tree that already threw will almost always throw again on re-render,
    // so recovery is a reload rather than a retry of the same children.
    const reload = this.props.onReload ?? reloadDocument
    return (
      <ErrorState
        title="예기치 못한 오류가 발생했습니다"
        message="게임을 다시 불러오면 진행 상황은 저장된 지점부터 이어집니다."
        errorCode={error.message}
        onRetry={reload}
        retryLabel="다시 불러오기"
      />
    )
  }
}
