import { useGameStore } from '../../runtime/gameStore'
import { GameHud, type GameHudProps } from '../GameUI'

export type HudContainerProps = Omit<
  GameHudProps,
  'observedEnemies' | 'threats' | 'score'
>

/**
 * Leaf that owns the combat-tick store slices.
 *
 * `adjustObservedEnemies` fires on every gaze freeze and unfreeze, and
 * `setThreat` writes a fresh array on every attack telegraph — both scale with
 * how much the player sweeps the vision cone, which is constantly. Subscribing
 * here instead of in App keeps that traffic away from the component that
 * renders the Canvas.
 */
export function HudContainer(props: HudContainerProps) {
  const observedEnemies = useGameStore((state) => state.observedEnemies)
  const threats = useGameStore((state) => state.threats)
  const score = useGameStore((state) => state.score)

  return (
    <GameHud
      {...props}
      observedEnemies={observedEnemies}
      threats={threats}
      score={score}
    />
  )
}
