import type { CSSProperties } from 'react'

import { useGameStore } from '../runtime/gameStore'
import { getHitVignetteProfile } from '../scene/hitVignette'

type VignetteStyle = CSSProperties & {
  '--boda-hit-opacity': number
  '--boda-hit-mid-opacity': number
  '--boda-hit-duration': string
}

export function DamageVignetteOverlay() {
  const hit = useGameStore((state) => state.lastPlayerHit)
  const maxHealth = useGameStore((state) => state.stats.maxHealth)
  const reducedMotion = useGameStore((state) => state.settings.reducedMotion)
  if (!hit) return null

  const profile = getHitVignetteProfile(hit.damage, maxHealth, reducedMotion)
  const style: VignetteStyle = {
    '--boda-hit-opacity': profile.opacity,
    '--boda-hit-mid-opacity': profile.opacity * 0.45,
    '--boda-hit-duration': `${profile.durationSeconds}s`,
  }

  return (
    <div
      key={hit.id}
      className="boda-damage-vignette"
      data-testid="damage-vignette"
      data-hit-id={hit.id}
      style={style}
      aria-hidden="true"
    />
  )
}
