import type { DifficultyRank } from '../game'

export interface SealOptionViewModel {
  readonly rank: DifficultyRank
  readonly name: string
  readonly payoutMultiplier: number
  readonly locked: boolean
  readonly summary: string
}

export interface SealDifficultySelectorProps {
  options: readonly SealOptionViewModel[]
  selected: number
  onSelect: (rank: number) => void
}

export function SealDifficultySelector({
  options,
  selected,
  onSelect,
}: SealDifficultySelectorProps) {
  const selectedOption = options.find((option) => option.rank === selected)

  return (
    <section className="boda-seal-select" aria-labelledby="boda-seal-title">
      <div className="boda-seal-select__heading">
        <div>
          <span>EXPEDITION MODE</span>
          <strong id="boda-seal-title">원정 모드</strong>
        </div>
        <small>파편 ×{selectedOption?.payoutMultiplier ?? 1}</small>
      </div>
      <div className="boda-seal-select__options" role="radiogroup">
        {options.map((option) => (
          <button
            key={option.rank}
            type="button"
            role="radio"
            aria-checked={selected === option.rank}
            aria-label={`${option.name}${option.locked ? ', 잠김' : ''}`}
            disabled={option.locked}
            data-locked={option.locked}
            data-testid={`difficulty-${option.rank}`}
            onClick={() => onSelect(option.rank)}
          >
            <small>
              {option.locked
                ? 'LOCKED'
                : option.rank === 1
                  ? 'STANDARD'
                  : 'ENDLESS'}
            </small>
            <strong>{option.name}</strong>
          </button>
        ))}
      </div>
      <p>{selectedOption?.summary}</p>
    </section>
  )
}
