export type GameButtonVariant = 'primary' | 'secondary' | 'danger' | 'ghost'

export interface GameButtonProps {
  children: ReactNode
  onClick?: () => void
  variant?: GameButtonVariant
  disabled?: boolean
  autoFocus?: boolean
  type?: 'button' | 'submit' | 'reset'
  className?: string
  testId?: string
  ariaLabel?: string
}

export function GameButton({
  children,
  onClick,
  variant = 'secondary',
  disabled = false,
  autoFocus = false,
  type = 'button',
  className,
  testId,
  ariaLabel,
}: GameButtonProps) {
  return (
    <button
      type={type}
      className={cx('boda-button', `boda-button--${variant}`, className)}
      onClick={onClick}
      disabled={disabled}
      autoFocus={autoFocus}
      data-testid={testId}
      aria-label={ariaLabel}
    >
      <span className="boda-button__edge" aria-hidden="true" />
      <span className="boda-button__label">{children}</span>
    </button>
  )
}

export interface TitleScreenProps {
  onStart: () => void
  onContinue?: () => void
  onOpenSettings?: () => void
  title?: string
  eyebrow?: string
  subtitle?: string
  description?: string
  version?: string
  busy?: boolean
  desktopArtSrc?: string
  mobileArtSrc?: string
  anyKeyLabel?: string
  statusLabel?: string
}

export function TitleScreen({
  onStart,
  onContinue,
  onOpenSettings,
  title = 'BODA',
  eyebrow = 'THE LAST GAZE',
  subtitle = '시선을 거두는 순간, 사냥이 시작된다',
  description = '어둠 속 존재를 응시해 멈추고, 시야 밖의 위협을 베어내세요.',
  version,
  busy = false,
  desktopArtSrc,
  mobileArtSrc,
  anyKeyLabel = '여기를 눌러 시작',
  statusLabel = '게임 시작 화면',
}: TitleScreenProps) {
  const activatedRef = useRef(false)
  const activate = onContinue ?? onStart

  useEffect(() => {
    activatedRef.current = false
  }, [busy, activate])

  const handleActivate = () => {
    if (busy || activatedRef.current) return
    activatedRef.current = true
    activate()
  }

  return (
    <main
      className="boda-ui boda-title boda-title--keyart"
      data-testid="title-screen"
      aria-label={statusLabel}
      aria-busy={busy}
    >
      {desktopArtSrc ? (
        <picture
          className="boda-title__keyart"
          aria-hidden="true"
          data-testid="title-keyart"
        >
          {mobileArtSrc ? (
            <source media="(max-width: 700px)" srcSet={mobileArtSrc} />
          ) : null}
          <img src={desktopArtSrc} alt="" draggable={false} />
        </picture>
      ) : null}
      <div className="boda-title__mist" aria-hidden="true" />
      <div className="boda-title__vignette" aria-hidden="true" />

      <section
        className="boda-title__content"
        aria-labelledby="boda-game-title"
      >
        <p className="boda-eyebrow">{eyebrow}</p>
        <h1 id="boda-game-title" className="boda-title__name">
          {title}
        </h1>
        <div className="boda-ornament" aria-hidden="true">
          <span />
          <i />
          <span />
        </div>
        <p className="boda-title__subtitle">{subtitle}</p>
        <p className="boda-title__description">{description}</p>

        <button
          type="button"
          className="boda-title__enter"
          onClick={handleActivate}
          disabled={busy}
          data-testid="start-game-button"
        >
          <span aria-hidden="true" />
          {busy ? '시스템 준비 중…' : anyKeyLabel}
          <span aria-hidden="true" />
        </button>
        {onContinue ? (
          <span className="boda-sr-only" data-testid="continue-game-button">
            계속하기
          </span>
        ) : null}
      </section>

      <p className="boda-title__hint">헤드폰 사용을 권장합니다</p>
      {onOpenSettings ? (
        <button
          type="button"
          className="boda-title__settings"
          onClick={onOpenSettings}
          disabled={busy}
          data-testid="open-settings-button"
        >
          설정
        </button>
      ) : null}
      {version ? <p className="boda-title__version">{version}</p> : null}
    </main>
  )
}

