interface ItemModifierViewModel {
  id: keyof StatModifiers
  label: string
  value: string
  tone: 'positive' | 'warning' | 'neutral'
}

function signedValue(value: number, suffix = ''): string {
  const rounded = Math.round(value * 10) / 10
  return `${rounded > 0 ? '+' : ''}${rounded}${suffix}`
}

function multiplierValue(value: number, invert = false): string {
  const delta = (value - 1) * 100 * (invert ? -1 : 1)
  return signedValue(delta, '%')
}

function itemModifierStats(
  modifiers: StatModifiers,
): readonly ItemModifierViewModel[] {
  const stats: ItemModifierViewModel[] = []
  const add = (
    id: keyof StatModifiers,
    label: string,
    value: string,
    numericValue: number,
    invertTone = false,
  ) => {
    const positive = invertTone ? numericValue < 0 : numericValue > 0
    const warning = invertTone ? numericValue > 0 : numericValue < 0
    stats.push({
      id,
      label,
      value,
      tone: positive ? 'positive' : warning ? 'warning' : 'neutral',
    })
  }

  if (modifiers.maxHealthAdd !== undefined) {
    add(
      'maxHealthAdd',
      '최대 생명력',
      signedValue(modifiers.maxHealthAdd),
      modifiers.maxHealthAdd,
    )
  }
  if (modifiers.attackDamageMultiplier !== undefined) {
    add(
      'attackDamageMultiplier',
      '공격력',
      multiplierValue(modifiers.attackDamageMultiplier),
      modifiers.attackDamageMultiplier - 1,
    )
  }
  if (modifiers.attackCooldownMultiplier !== undefined) {
    add(
      'attackCooldownMultiplier',
      '공격 속도',
      multiplierValue(modifiers.attackCooldownMultiplier, true),
      1 - modifiers.attackCooldownMultiplier,
    )
  }
  if (modifiers.moveSpeedMultiplier !== undefined) {
    add(
      'moveSpeedMultiplier',
      '이동 속도',
      multiplierValue(modifiers.moveSpeedMultiplier),
      modifiers.moveSpeedMultiplier - 1,
    )
  }
  if (modifiers.projectileSpeedMultiplier !== undefined) {
    add(
      'projectileSpeedMultiplier',
      '투사체 속도',
      multiplierValue(modifiers.projectileSpeedMultiplier),
      modifiers.projectileSpeedMultiplier - 1,
    )
  }
  if (modifiers.dodgeCooldownMultiplier !== undefined) {
    add(
      'dodgeCooldownMultiplier',
      '회피 재사용',
      multiplierValue(modifiers.dodgeCooldownMultiplier, true),
      1 - modifiers.dodgeCooldownMultiplier,
    )
  }
  if (modifiers.visionRangeAdd !== undefined) {
    add(
      'visionRangeAdd',
      '응시 거리',
      signedValue(modifiers.visionRangeAdd),
      modifiers.visionRangeAdd,
    )
  }
  if (modifiers.visionFovDegAdd !== undefined) {
    add(
      'visionFovDegAdd',
      '응시 각도',
      signedValue(modifiers.visionFovDegAdd, '°'),
      modifiers.visionFovDegAdd,
    )
  }

  return stats
}

function lobbyItemState(
  item: ItemDefinition,
  currency: number,
  ownedItemIds: ReadonlySet<ItemId>,
  equippedItemIds: EquipmentLoadout,
): LobbyItemCardState {
  if (equippedItemIds[item.slot] === item.id) return 'equipped'
  if (ownedItemIds.has(item.id)) return 'owned'
  return currency >= item.cost ? 'available' : 'unaffordable'
}

interface LobbyItemCardProps {
  item: ItemDefinition
  state: LobbyItemCardState
  busy: boolean
  onPurchase: (itemId: ItemId) => void
  onEquip: (itemId: ItemId) => void
}

function LobbyItemCard({
  item,
  state,
  busy,
  onPurchase,
  onEquip,
}: LobbyItemCardProps) {
  const modifierStats = itemModifierStats(item.modifiers)
  const isPurchaseAction = state === 'available' || state === 'unaffordable'
  const isDisabled = busy || state === 'unaffordable' || state === 'equipped'
  const stateLabel =
    state === 'equipped'
      ? '장착 중'
      : state === 'owned'
        ? '보유 중'
        : state === 'unaffordable'
          ? '파편 부족'
          : '구매 가능'

  return (
    <article
      className="boda-lobby-item"
      data-state={state}
      data-slot={item.slot}
      data-testid={`lobby-item-${item.id}`}
    >
      <div className="boda-lobby-item__sigil" aria-hidden="true">
        <EquipmentIcon slot={item.slot} />
      </div>
      <div className="boda-lobby-item__heading">
        <span>{LOBBY_SLOT_LABELS[item.slot]}</span>
        <small>{stateLabel}</small>
      </div>
      <h3>{item.name}</h3>
      <p>{item.description}</p>
      <dl className="boda-lobby-item__stats" aria-label={`${item.name} 능력치`}>
        {modifierStats.length > 0 ? (
          modifierStats.map((stat) => (
            <div key={stat.id} data-tone={stat.tone}>
              <dt>{stat.label}</dt>
              <dd>{stat.value}</dd>
            </div>
          ))
        ) : (
          <div data-tone="neutral">
            <dt>성향</dt>
            <dd>균형</dd>
          </div>
        )}
      </dl>
      <div className="boda-lobby-item__footer">
        <span className="boda-lobby-item__price">
          <i aria-hidden="true" />
          <span className="boda-sr-only">가격 </span>
          {item.cost.toLocaleString('ko-KR')}
        </span>
        <GameButton
          variant={state === 'available' ? 'primary' : 'secondary'}
          className="boda-lobby-item__action"
          disabled={isDisabled}
          onClick={() =>
            isPurchaseAction ? onPurchase(item.id) : onEquip(item.id)
          }
          testId={
            isPurchaseAction
              ? `purchase-item-${item.id}`
              : `equip-item-${item.id}`
          }
          ariaLabel={
            isPurchaseAction
              ? `${item.name} 구매`
              : `${item.name} ${state === 'equipped' ? '장착 중' : '장착'}`
          }
        >
          {state === 'equipped'
            ? '장착 중'
            : state === 'owned'
              ? '장착'
              : state === 'unaffordable'
                ? '파편 부족'
                : '구매'}
        </GameButton>
      </div>
    </article>
  )
}

