export interface HealthDisplayProps {
  current: number
  maximum: number
  label?: string
  dangerThreshold?: number
  className?: string
}

export function HealthDisplay({
  current,
  maximum,
  label = '생명력',
  dangerThreshold = 0.25,
  className,
}: HealthDisplayProps) {
  const safeMaximum = Math.max(1, maximum)
  const safeCurrent = clamp(current, 0, safeMaximum)
  const ratio = safeCurrent / safeMaximum
  const percent = Math.round(ratio * 100)
  const style = { '--boda-health': `${percent}%` } as CSSProperties
  const critical = ratio <= dangerThreshold

  return (
    <section
      className={cx('boda-ui boda-health', className)}
      data-state={critical ? 'critical' : 'stable'}
      data-testid="health-display"
      aria-label={`${label} ${Math.ceil(safeCurrent)} / ${Math.ceil(safeMaximum)}`}
    >
      {/*
        The one combat state worth interrupting for. Announcing every point of
        damage would be as noisy as the gaze counter used to be, so this only
        speaks when the player crosses into danger.
      */}
      <span className="boda-sr-only" role="status" aria-live="assertive">
        {critical ? `${label} 위험` : ''}
      </span>
      <div className="boda-health__heading">
        <span className="boda-health__label">{label}</span>
        <span className="boda-health__value" data-testid="health-value">
          {Math.ceil(safeCurrent)} <i>/</i> {Math.ceil(safeMaximum)}
        </span>
      </div>
      <div
        className="boda-health__track"
        role="progressbar"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={safeMaximum}
        aria-valuenow={safeCurrent}
      >
        <span className="boda-health__fill" style={style} />
        <span className="boda-health__shine" aria-hidden="true" />
      </div>
    </section>
  )
}

