export type ThreatIntensity = 'guarded' | 'elevated' | 'critical'

export interface ThreatMarkerPosition {
  xPercent: number
  yPercent: number
}

function safeThreatAngle(angleDeg: number): number {
  return Number.isFinite(angleDeg) ? angleDeg : 0
}

function getThreatMarkerPosition(angleDeg: number): ThreatMarkerPosition {
  const safeAngle = safeThreatAngle(angleDeg)
  const radians = (safeAngle * Math.PI) / 180
  const directionX = Math.sin(radians)
  const directionY = -Math.cos(radians)
  const horizontalReach = 45
  const verticalReach = 41
  const horizontalScale =
    Math.abs(directionX) < 0.000_001
      ? Number.POSITIVE_INFINITY
      : horizontalReach / Math.abs(directionX)
  const verticalScale =
    Math.abs(directionY) < 0.000_001
      ? Number.POSITIVE_INFINITY
      : verticalReach / Math.abs(directionY)
  const scale = Math.min(horizontalScale, verticalScale)
  const round = (value: number) => Math.round(value * 1_000) / 1_000

  return {
    xPercent: round(50 + directionX * scale),
    yPercent: round(50 + directionY * scale),
  }
}

function getThreatIntensity(
  threats: readonly ThreatWarning[],
  combatTier: CombatTier | 'boss' | null,
): ThreatIntensity {
  if (
    combatTier === 'boss' ||
    combatTier === 3 ||
    threats.length >= 3 ||
    threats.some((threat) => threat.kind === 'boss')
  ) {
    return 'critical'
  }
  if (combatTier === 2 || threats.length >= 2) return 'elevated'
  return 'guarded'
}

function threatDirectionLabel(angleDeg: number): string {
  const normalized = ((safeThreatAngle(angleDeg) % 360) + 360) % 360
  const labels = [
    '전방',
    '우측 전방',
    '우측',
    '우측 후방',
    '후방',
    '좌측 후방',
    '좌측',
    '좌측 전방',
  ] as const
  return labels[Math.round(normalized / 45) % labels.length]
}

function threatKindLabel(kind: ThreatWarning['kind']): string {
  if (kind === 'ranged') return '원거리'
  if (kind === 'boss') return '보스'
  return '근접'
}

export interface ThreatIndicatorsProps {
  threats: readonly ThreatWarning[]
  combatTier: CombatTier | 'boss' | null
}

export function ThreatIndicators({
  threats,
  combatTier,
}: ThreatIndicatorsProps) {
  if (threats.length === 0) return null

  const intensity = getThreatIntensity(threats, combatTier)
  const intensityLabel =
    intensity === 'critical'
      ? '치명적'
      : intensity === 'elevated'
        ? '고조'
        : '경계'
  const tierLabel =
    combatTier === 'boss' ? '보스 위협' : `위협 단계 ${combatTier ?? 1}`

  return (
    <section
      className="boda-threats"
      data-intensity={intensity}
      data-tier={combatTier ?? 1}
      data-testid="threat-indicators"
    >
      {/*
        Deliberately not a live region: this changes several times a second
        during combat, and narrating it continuously buries the announcements
        that matter. It stays labelled so it can be queried on demand.
      */}
      <div
        className="boda-threats__summary"
        role="group"
        aria-label={`${tierLabel}, 위험도 ${intensityLabel}, 공격 준비 ${threats.length}개`}
      >
        <span>{tierLabel}</span>
        <strong>
          {intensityLabel} · {threats.length}
        </strong>
      </div>
      <ul className="boda-threats__markers" aria-label="공격 방향 경고">
        {threats.map((threat) => {
          const angleDeg = safeThreatAngle(threat.angleDeg)
          const position = getThreatMarkerPosition(angleDeg)
          const markerStyle = {
            left: `${position.xPercent}%`,
            top: `${position.yPercent}%`,
            '--boda-threat-angle': `${angleDeg}deg`,
            '--boda-threat-duration': `${Math.max(240, threat.durationMs)}ms`,
          } as CSSProperties

          return (
            <li
              key={threat.id}
              className="boda-threat-marker"
              data-kind={threat.kind}
              data-testid={`threat-marker-${threat.id}`}
              style={markerStyle}
              aria-label={`${threatDirectionLabel(threat.angleDeg)}에서 ${threatKindLabel(threat.kind)} 공격 준비`}
            >
              <span className="boda-threat-marker__arrow" aria-hidden="true" />
              <span className="boda-threat-marker__core" aria-hidden="true" />
            </li>
          )
        })}
      </ul>
    </section>
  )
}

