const ROUTE_RISK_LABELS: Record<RouteRisk, string> = {
  stable: '안정 경로',
  volatile: '변동 경로',
  boss: '보스 경로',
}

const ROUTE_MAP_WIDTH = 600
const ROUTE_MAP_HEIGHT = 100
const ROUTE_MAP_CURRENT = { x: ROUTE_MAP_WIDTH / 2, y: 18 } as const
const ROUTE_MAP_CHOICE_Y = 82

function getRouteMapChoiceX(index: number, count: number): number {
  if (count <= 1) return ROUTE_MAP_WIDTH / 2
  if (count === 2) return index === 0 ? 170 : 430
  const inset = 90
  return inset + ((ROUTE_MAP_WIDTH - inset * 2) * index) / (count - 1)
}

function RouteMap({ choices }: { choices: readonly RouteChoiceViewModel[] }) {
  const points = choices.map((choice, index) => ({
    choice,
    x: getRouteMapChoiceX(index, choices.length),
    y: ROUTE_MAP_CHOICE_Y,
  }))

  return (
    <svg
      className="boda-route-map"
      viewBox={`0 0 ${ROUTE_MAP_WIDTH} ${ROUTE_MAP_HEIGHT}`}
      preserveAspectRatio="xMidYMid meet"
      aria-hidden="true"
      focusable="false"
      data-testid="route-map"
      data-choice-count={choices.length}
    >
      <g className="boda-route-map__connectors">
        {points.map(({ choice, x, y }) => (
          <line
            key={choice.id}
            className="boda-route-map__connector"
            x1={ROUTE_MAP_CURRENT.x}
            y1={ROUTE_MAP_CURRENT.y}
            x2={x}
            y2={y}
            data-testid={`route-map-connector-${choice.id}`}
            data-target-risk={choice.risk}
          />
        ))}
      </g>
      <g className="boda-route-map__nodes">
        <circle
          className="boda-route-map__node boda-route-map__node--current"
          cx={ROUTE_MAP_CURRENT.x}
          cy={ROUTE_MAP_CURRENT.y}
          r="12"
          data-testid="route-map-current-node"
          data-marker-shape="circle"
        />
        {points.map(({ choice, x, y }) => {
          const commonProps = {
            className: `boda-route-map__node boda-route-map__node--${choice.risk}`,
            'data-testid': `route-map-node-${choice.id}`,
            'data-risk': choice.risk,
          }
          if (choice.risk === 'volatile') {
            return (
              <rect
                key={choice.id}
                {...commonProps}
                x={x - 10}
                y={y - 10}
                width="20"
                height="20"
                transform={`rotate(45 ${x} ${y})`}
                data-marker-shape="diamond"
                data-center-x={x}
                data-center-y={y}
              />
            )
          }
          if (choice.risk === 'boss') {
            return (
              <polygon
                key={choice.id}
                {...commonProps}
                points={`${x},${y - 13} ${x + 12},${y - 6} ${x + 12},${
                  y + 6
                } ${x},${y + 13} ${x - 12},${y + 6} ${x - 12},${y - 6}`}
                data-marker-shape="boss"
                data-center-x={x}
                data-center-y={y}
              />
            )
          }
          return (
            <circle
              key={choice.id}
              {...commonProps}
              cx={x}
              cy={y}
              r="12"
              data-marker-shape="circle"
              data-center-x={x}
              data-center-y={y}
            />
          )
        })}
      </g>
    </svg>
  )
}

