export type BootStage =
  'system' | 'code' | 'audio' | 'assets' | 'physics' | 'shaders' | 'finalizing'

export interface BootProgress {
  readonly stage: BootStage
  readonly progress: number
  readonly label: string
  readonly detail?: string
  readonly transfer?: BootTransferProgress
}

export interface BootTransferProgress {
  readonly loadedBytes: number
  readonly totalBytes: number
}

export interface BootTaskContext {
  readonly signal: AbortSignal
  readonly report: (
    progress: number,
    detail?: string,
    transfer?: BootTransferProgress,
  ) => void
}

export interface BootTask {
  readonly stage: BootStage
  readonly label: string
  readonly weight: number
  readonly critical?: boolean
  /**
   * Watchdog for this task. Defaults to the task's weight scaled by
   * DEFAULT_BOOT_MS_PER_WEIGHT. Pass 0 to opt out.
   */
  readonly timeoutMs?: number
  readonly run: (context: BootTaskContext) => Promise<void>
}

export interface BootWarning {
  readonly stage: BootStage
  readonly message: string
}

export interface BootResult {
  readonly warnings: readonly BootWarning[]
}

interface RuntimeAssetManifestEntry {
  readonly runtimePath?: unknown
  readonly runtimeBytes?: unknown
  readonly bundles?: unknown
}

interface RuntimeAssetManifest {
  readonly assets?: unknown
}

function clampProgress(value: number): number {
  if (!Number.isFinite(value)) return 0
  return Math.max(0, Math.min(1, value))
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/**
 * Generous by design. This is a watchdog against a connection that never
 * settles, not a performance target — a slow machine should still boot.
 */
export const DEFAULT_BOOT_MS_PER_WEIGHT = 20_000

export class BootTimeoutError extends Error {
  constructor(
    readonly stage: BootStage,
    label: string,
    timeoutMs: number,
  ) {
    super(
      `${label} 단계가 ${Math.round(timeoutMs / 1000)}초 안에 끝나지 않았습니다.`,
    )
    this.name = 'BootTimeoutError'
  }
}

/**
 * Races a task against its deadline and aborts its own work when the deadline
 * wins, so a stalled fetch is cancelled rather than left running behind a
 * loading screen the player cannot leave.
 */
async function runTaskWithDeadline(
  task: BootTask,
  report: (value: number, detail?: string) => void,
  signal: AbortSignal,
): Promise<void> {
  const timeoutMs = task.timeoutMs ?? task.weight * DEFAULT_BOOT_MS_PER_WEIGHT
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
    return task.run({ signal, report })
  }

  const controller = new AbortController()
  const abortFromOuter = () => controller.abort(signal.reason)
  signal.addEventListener('abort', abortFromOuter, { once: true })
  let timer: ReturnType<typeof setTimeout> | undefined
  let timerStartedAt = 0
  let remainingMs = timeoutMs
  let rejectDeadline: ((reason: unknown) => void) | undefined
  const visibilityDocument =
    typeof document === 'undefined' ? undefined : document

  const expire = () => {
    timer = undefined
    const error = new BootTimeoutError(task.stage, task.label, timeoutMs)
    controller.abort(error)
    rejectDeadline?.(error)
  }
  const armDeadline = () => {
    if (timer !== undefined || visibilityDocument?.hidden) return
    timerStartedAt = Date.now()
    timer = setTimeout(expire, Math.max(0, remainingMs))
  }
  const pauseDeadline = () => {
    if (timer === undefined) return
    clearTimeout(timer)
    timer = undefined
    remainingMs = Math.max(0, remainingMs - (Date.now() - timerStartedAt))
  }
  const handleVisibilityChange = () => {
    if (visibilityDocument?.hidden) pauseDeadline()
    else armDeadline()
  }

  try {
    await new Promise<void>((resolve, reject) => {
      rejectDeadline = reject
      visibilityDocument?.addEventListener(
        'visibilitychange',
        handleVisibilityChange,
      )
      armDeadline()
      task.run({ signal: controller.signal, report }).then(resolve, reject)
    })
  } finally {
    if (timer !== undefined) clearTimeout(timer)
    visibilityDocument?.removeEventListener(
      'visibilitychange',
      handleVisibilityChange,
    )
    signal.removeEventListener('abort', abortFromOuter)
  }
}

/** Runs measured boot work sequentially and reports monotonic weighted progress. */
export async function runBootTasks(
  tasks: readonly BootTask[],
  onProgress: (progress: BootProgress) => void,
  signal: AbortSignal,
): Promise<BootResult> {
  const runnable = tasks.filter((task) => task.weight > 0)
  const totalWeight = runnable.reduce((sum, task) => sum + task.weight, 0)
  if (totalWeight <= 0) {
    onProgress({ stage: 'finalizing', progress: 1, label: '준비 완료' })
    return { warnings: [] }
  }

  const warnings: BootWarning[] = []
  let completedWeight = 0
  let lastOverall = 0

  for (const task of runnable) {
    signal.throwIfAborted()
    let taskProgress = 0
    const report = (
      value: number,
      detail?: string,
      transfer?: BootTransferProgress,
    ) => {
      taskProgress = Math.max(taskProgress, clampProgress(value))
      const overall = Math.max(
        lastOverall,
        (completedWeight + task.weight * taskProgress) / totalWeight,
      )
      lastOverall = overall
      onProgress({
        stage: task.stage,
        progress: overall,
        label: task.label,
        detail,
        transfer,
      })
    }

    report(0)
    try {
      await runTaskWithDeadline(task, report, signal)
    } catch (error) {
      if (signal.aborted) throw error
      if (task.critical !== false) throw error
      warnings.push({ stage: task.stage, message: errorMessage(error) })
    }
    report(1)
    completedWeight += task.weight
  }

  onProgress({
    stage: 'finalizing',
    progress: 1,
    label: '준비 완료',
  })
  return { warnings }
}

/** Fetches and consumes a response body so progress reflects transferred bytes. */
export async function preloadUrl(
  url: string,
  context: BootTaskContext,
): Promise<void> {
  const response = await fetch(url, { signal: context.signal })
  if (!response.ok) throw new Error(`${url} (${response.status})`)

  const total = Number(response.headers.get('content-length'))
  if (!response.body || !Number.isFinite(total) || total <= 0) {
    await response.arrayBuffer()
    context.report(1)
    return
  }

  const reader = response.body.getReader()
  let received = 0
  while (true) {
    const chunk = await reader.read()
    if (chunk.done) break
    received += chunk.value.byteLength
    context.report(received / total)
  }
  context.report(1)
}

export async function decodeImage(
  url: string,
  context: BootTaskContext,
): Promise<void> {
  if (typeof Image !== 'function') {
    await preloadUrl(url, context)
    return
  }
  const image = new Image()
  image.decoding = 'async'
  image.src = url
  await image.decode()
  context.report(1)
}

export function selectBundleRuntimePaths(
  manifest: RuntimeAssetManifest,
  bundle: string,
): readonly string[] {
  return selectBundleRuntimeAssets(manifest, bundle).map(
    (asset) => asset.runtimePath,
  )
}

export interface RuntimeBundleAsset {
  readonly runtimePath: string
  readonly runtimeBytes?: number
}

export function selectBundleRuntimeAssets(
  manifest: RuntimeAssetManifest,
  bundle: string,
): readonly RuntimeBundleAsset[] {
  if (!Array.isArray(manifest.assets)) return []
  const assets = manifest.assets.flatMap((candidate) => {
    if (typeof candidate !== 'object' || candidate === null) return []
    const entry = candidate as RuntimeAssetManifestEntry
    if (
      typeof entry.runtimePath !== 'string' ||
      !Array.isArray(entry.bundles) ||
      !entry.bundles.includes(bundle) ||
      entry.runtimePath.startsWith('/') ||
      entry.runtimePath.includes('..')
    ) {
      return []
    }
    return [
      {
        runtimePath: entry.runtimePath,
        runtimeBytes:
          typeof entry.runtimeBytes === 'number' &&
          Number.isFinite(entry.runtimeBytes) &&
          entry.runtimeBytes > 0
            ? entry.runtimeBytes
            : undefined,
      },
    ]
  })
  return [
    ...new Map(assets.map((asset) => [asset.runtimePath, asset])).values(),
  ]
}

/** Loads every manifest asset in a named bundle while reporting aggregate work. */
export async function preloadAssetBundle(
  manifestUrl: string,
  assetBaseUrl: string,
  bundle: string,
  context: BootTaskContext,
): Promise<void> {
  const response = await fetch(manifestUrl, { signal: context.signal })
  if (!response.ok) throw new Error(`${manifestUrl} (${response.status})`)
  const manifest = (await response.json()) as RuntimeAssetManifest
  const assets = selectBundleRuntimeAssets(manifest, bundle)
  if (assets.length === 0) {
    context.report(1, '초기 번들 없음')
    return
  }

  const knownSizes = assets.flatMap((asset) =>
    asset.runtimeBytes === undefined ? [] : [asset.runtimeBytes],
  )
  const fallbackSize =
    knownSizes.length > 0
      ? knownSizes.reduce((sum, size) => sum + size, 0) / knownSizes.length
      : 1
  const weights = assets.map((asset) => asset.runtimeBytes ?? fallbackSize)
  const totalBytes = weights.reduce((sum, size) => sum + size, 0)
  const progress = assets.map(() => 0)
  const failures: string[] = []
  const reportAggregate = (detail?: string) => {
    const loadedBytes = progress.reduce(
      (sum, value, index) => sum + value * weights[index]!,
      0,
    )
    context.report(loadedBytes / totalBytes, detail, {
      loadedBytes: Math.round(loadedBytes),
      totalBytes: Math.round(totalBytes),
    })
  }

  for (let offset = 0; offset < assets.length; offset += 6) {
    const batch = assets.slice(offset, offset + 6)
    await Promise.all(
      batch.map(async (asset, batchIndex) => {
        const index = offset + batchIndex
        try {
          await preloadUrl(`${assetBaseUrl}${asset.runtimePath}`, {
            signal: context.signal,
            report: (value) => {
              progress[index] = clampProgress(value)
              reportAggregate(`${index + 1} / ${assets.length}`)
            },
          })
        } catch {
          failures.push(asset.runtimePath)
        } finally {
          progress[index] = 1
          reportAggregate(
            `${Math.min(offset + batch.length, assets.length)} / ${assets.length}`,
          )
        }
      }),
    )
  }

  if (failures.length > 0) {
    throw new Error(`초기 에셋 ${failures.length}개를 불러오지 못했습니다.`)
  }
}

/** Waits for rendered frames, used to warm post-processing allocations honestly. */
export async function waitForAnimationFrames(
  count: number,
  signal: AbortSignal,
): Promise<void> {
  const frameCount = Math.max(0, Math.floor(count))
  for (let index = 0; index < frameCount; index += 1) {
    signal.throwIfAborted()
    if (typeof requestAnimationFrame !== 'function') {
      await Promise.resolve()
      continue
    }
    await new Promise<void>((resolve, reject) => {
      const onAbort = () => reject(signal.reason)
      signal.addEventListener('abort', onAbort, { once: true })
      requestAnimationFrame(() => {
        signal.removeEventListener('abort', onAbort)
        resolve()
      })
    })
  }
}
