export type ScreenTransitionState = 'idle' | 'covering' | 'revealing'

export function ScreenTransitionOverlay({
  state,
}: {
  state: ScreenTransitionState
}) {
  return (
    <div
      className="boda-screen-transition"
      data-state={state}
      data-testid="screen-transition"
      aria-hidden="true"
    />
  )
}
