import {
  createDefaultSave,
  loadSave,
  serializeSave,
  type SaveData,
} from '../game'

const SAVE_KEY = 'boda.save.v5'
const PREVIOUS_SAVE_KEYS = [
  'boda.save.v4',
  'boda.save.v3',
  'boda.save.v2',
  'boda.save.v1',
] as const
const QUARANTINE_KEY_PREFIX = 'boda.save.quarantine.'
const VISION_ASSIST_KEY = 'boda.vision-assist.v1'

export interface LocalSaveLoad {
  readonly data: SaveData
  /** True when a stored key produced a usable save rather than a fresh default. */
  readonly recovered: boolean
}

/**
 * Preserves bytes that were present but could not be read — a save written by
 * a newer build, or one damaged in storage. The quarantine key is stable per
 * source key rather than timestamped, so a machine that cannot write back to
 * SAVE_KEY re-quarantines the same slot instead of growing a new entry on
 * every reload.
 */
function quarantineRawSave(key: string, raw: string): void {
  try {
    window.localStorage.setItem(`${QUARANTINE_KEY_PREFIX}${key}`, raw)
  } catch {
    // Storage may be full or disabled; the source key is left untouched.
  }
}

export function readLocalSave(): LocalSaveLoad {
  try {
    for (const key of [SAVE_KEY, ...PREVIOUS_SAVE_KEYS]) {
      const raw = window.localStorage.getItem(key)
      if (raw === null) continue
      const loaded = loadSave(raw)
      if (loaded.status !== 'reset')
        return { data: loaded.data, recovered: true }
      if (raw.trim() !== '') quarantineRawSave(key, raw)
    }
    return { data: createDefaultSave(), recovered: false }
  } catch {
    return { data: createDefaultSave(), recovered: false }
  }
}

export function removeMigratedSaveKeys(): void {
  for (const key of PREVIOUS_SAVE_KEYS) window.localStorage.removeItem(key)
}

export function writeLocalSave(save: SaveData): boolean {
  try {
    window.localStorage.setItem(SAVE_KEY, serializeSave(save))
    return true
  } catch {
    // Storage may be disabled; gameplay remains available for this session.
    return false
  }
}

export function readVisionAssist(): number | null {
  try {
    const raw = window.localStorage.getItem(VISION_ASSIST_KEY)
    if (raw === null || raw.trim() === '') return null
    const value = Number(raw)
    return Number.isFinite(value) && value >= 0 && value <= 1 ? value : null
  } catch {
    return null
  }
}

export function writeVisionAssist(value: number): void {
  try {
    window.localStorage.setItem(VISION_ASSIST_KEY, String(value))
  } catch {
    // Storage may be disabled; keep the setting for this session.
  }
}
