import { UPGRADES, type UpgradeId } from '../game'

export function getUpgradeOptions(ids: readonly UpgradeId[]) {
  return ids.map((id) => {
    const upgrade = UPGRADES.find((candidate) => candidate.id === id)
    if (!upgrade) throw new Error(`Unknown upgrade: ${id}`)
    return {
      id: upgrade.id,
      name: upgrade.name,
      description: upgrade.description,
      iconId: upgrade.id,
      rarity:
        id === 'iron-heart' || id === 'gale-step'
          ? ('rare' as const)
          : ('uncommon' as const),
      category:
        id === 'far-sight' ? '시야' : id === 'iron-heart' ? '생존' : '전투',
    }
  })
}
