import { StrictMode } from 'react'
import { flushSync } from 'react-dom'
import { createRoot } from 'react-dom/client'

import App from './App'
import type { BootProgress } from './runtime/boot'
import { RootErrorBoundary } from './ui/RootErrorBoundary'

export interface MountApplicationOptions {
  autoStart?: boolean
}

export function mountApplication({
  autoStart = false,
}: MountApplicationOptions = {}): void {
  const container = document.getElementById('root')
  if (!container) throw new Error('Missing #root element')

  const root = createRoot(container)
  container.inert = true
  container.setAttribute('aria-hidden', 'true')
  let revealed = false
  let bootScreenReady = false
  let startupFallback: number | undefined
  let lastProgress = 0

  const clearStartupFallback = () => {
    if (startupFallback === undefined) return
    window.clearTimeout(startupFallback)
    startupFallback = undefined
  }

  const revealApplication = () => {
    if (revealed) return
    revealed = true
    clearStartupFallback()
    window.__BODA_CLEAR_STARTUP_WATCHDOG__?.()
    container.inert = false
    container.removeAttribute('inert')
    container.removeAttribute('aria-hidden')
    document.getElementById('boda-static-title')?.remove()
  }

  const updateStaticBootProgress = (progress: BootProgress) => {
    if (revealed) return
    const nextProgress = Math.max(
      lastProgress,
      Math.min(1, Number.isFinite(progress.progress) ? progress.progress : 0),
    )
    lastProgress = nextProgress
    const percent = Math.round(nextProgress * 100)
    const progressBar = document.querySelector<HTMLElement>(
      '.boda-static-progress',
    )
    const progressFill = progressBar?.querySelector<HTMLElement>('span')
    const output = document.querySelector<HTMLOutputElement>(
      '.boda-static-percent',
    )
    const detail = document.getElementById('boda-static-loading-detail')
    if (progressFill) progressFill.style.width = `${percent}%`
    progressBar?.setAttribute('aria-valuenow', String(percent))
    if (output) output.value = `${percent}%`
    if (detail) {
      detail.textContent = progress.detail
        ? `${progress.label} · ${progress.detail}`
        : progress.label
    }
  }

  const showDelayedStartupError = () => {
    if (revealed) return
    startupFallback = undefined
    if (document.hidden) {
      armStartupWatchdog()
      return
    }
    window.__BODA_CLEAR_STARTUP_WATCHDOG__?.()
    const detail = document.getElementById('boda-static-loading-detail')
    const message = document.getElementById('boda-static-message')
    const retry = document.getElementById('boda-static-retry')
    const loader = document.querySelector<HTMLElement>('.boda-static-loader')
    const loading = document.getElementById('boda-static-loading')
    if (detail) detail.textContent = '게임 시작이 예상보다 오래 걸립니다.'
    if (message) {
      message.textContent = '다시 시도하면 타이틀부터 안전하게 시작합니다.'
      message.hidden = false
    }
    if (loader) loader.hidden = true
    if (loading) loading.setAttribute('aria-busy', 'false')
    if (retry instanceof HTMLButtonElement) {
      retry.hidden = false
      retry.addEventListener('click', () => window.location.reload(), {
        once: true,
      })
      retry.focus()
    }
  }

  const armStartupWatchdog = () => {
    if (revealed || bootScreenReady || startupFallback !== undefined) return
    startupFallback = window.setTimeout(showDelayedStartupError, 3_000)
  }

  const acknowledgeBootScreen = () => {
    if (revealed || bootScreenReady) return
    bootScreenReady = true
    clearStartupFallback()
    window.__BODA_CLEAR_STARTUP_WATCHDOG__?.()
  }

  const completeBoot = () => {
    if (revealed) return
    updateStaticBootProgress({
      stage: 'finalizing',
      progress: 1,
      label: '게임 준비 완료',
      detail: '로비를 여는 중',
    })
    requestAnimationFrame(() => requestAnimationFrame(revealApplication))
  }

  const reportBootError = (message: string) => {
    if (revealed) return
    showDelayedStartupError()
    const detail = document.getElementById('boda-static-loading-detail')
    if (detail) detail.textContent = message
  }

  flushSync(() => {
    root.render(
      <StrictMode>
        <RootErrorBoundary>
          <App
            autoStart={autoStart}
            onBootScreenReady={autoStart ? acknowledgeBootScreen : undefined}
            onBootProgress={autoStart ? updateStaticBootProgress : undefined}
            onBootComplete={autoStart ? completeBoot : undefined}
            onBootError={autoStart ? reportBootError : undefined}
          />
        </RootErrorBoundary>
      </StrictMode>,
    )
  })

  if (autoStart) {
    // A stalled React mount stays recoverable instead of exposing an empty
    // root beneath the static loader.
    armStartupWatchdog()
  } else {
    requestAnimationFrame(revealApplication)
  }
}
