import type { GameSettings, MotionPreference } from '../game'

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)'

/**
 * Resolves the stored preference for saves written before `motionPreference`
 * existed.
 *
 * `cameraShake: true` is the untouched default rather than a choice, so those
 * saves fall through to `auto` and start honouring the OS. A player who
 * actually turned shake off is preserved as an explicit `reduced`.
 */
export function storedMotionPreference(
  settings: GameSettings,
): MotionPreference {
  if (settings.motionPreference) return settings.motionPreference
  return settings.cameraShake === false ? 'reduced' : 'auto'
}

export function resolveReducedMotion(
  preference: MotionPreference,
  systemPrefersReduced: boolean,
): boolean {
  if (preference === 'reduced') return true
  if (preference === 'full') return false
  return systemPrefersReduced
}

export function systemPrefersReducedMotion(): boolean {
  if (typeof window.matchMedia !== 'function') return false
  try {
    return window.matchMedia(REDUCED_MOTION_QUERY).matches
  } catch {
    return false
  }
}

/**
 * Subscribes to OS-level changes. Returns a no-op unsubscribe when the media
 * query is unavailable, so callers never need to branch.
 */
export function watchReducedMotion(
  onChange: (systemPrefersReduced: boolean) => void,
): () => void {
  if (typeof window.matchMedia !== 'function') return () => {}
  let query: MediaQueryList
  try {
    query = window.matchMedia(REDUCED_MOTION_QUERY)
  } catch {
    return () => {}
  }

  const handler = (event: MediaQueryListEvent) => onChange(event.matches)
  // Safari below 14 only has the deprecated listener API.
  if (typeof query.addEventListener === 'function') {
    query.addEventListener('change', handler)
    return () => query.removeEventListener('change', handler)
  }
  query.addListener(handler)
  return () => query.removeListener(handler)
}
