export interface HitVignetteProfile {
  readonly strength: number
  readonly opacity: number
  readonly durationSeconds: number
}

export function getHitVignetteProfile(
  damage: number,
  maxHealth: number,
  reducedMotion: boolean,
): HitVignetteProfile {
  const ratio =
    Number.isFinite(damage) && Number.isFinite(maxHealth) && maxHealth > 0
      ? Math.max(0, damage) / maxHealth
      : 0
  const severity = Math.min(1, ratio / 0.45)
  const strength = 0.42 + severity * 0.58

  return {
    strength,
    opacity: reducedMotion ? 0.62 + severity * 0.16 : 0.68 + severity * 0.28,
    durationSeconds: reducedMotion ? 0.3 : 0.65 + severity * 0.45,
  }
}
