function encounterBannerViewModel(
  event: EncounterPresentationEvent,
): EncounterBannerViewModel {
  const badges =
    event.kind === 'start'
      ? [
          ENCOUNTER_RISK_LABELS[event.risk],
          event.mutationId ? MUTATION_LABELS[event.mutationId] : undefined,
          event.eliteCount > 0 ? `정예 ${event.eliteCount}` : undefined,
        ].filter((label): label is string => label !== undefined)
      : []

  return {
    id: event.id,
    kind: event.kind,
    chamber: event.chamber,
    title: event.roomName,
    subtitle:
      event.kind === 'start'
        ? event.boss
          ? '마지막 존재를 처치하세요'
          : '모든 존재를 처치하세요'
        : `정화 완료 · ${ENCOUNTER_NEXT_STEP_LABELS[event.nextStep]}`,
    boss: event.boss,
    badges,
  }
}

