  const shrine = useGameStore((state) => state.shrine)
  const beginBoot = useGameStore((state) => state.beginBoot)
  const enterLobbyStore = useGameStore((state) => state.enterLobby)
  const beginPlaying = useGameStore((state) => state.beginPlaying)
