  const returnToTitle = useGameStore((state) => state.returnToTitle)
  const togglePause = useGameStore((state) => state.togglePause)
  const chooseRuneStore = useGameStore((state) => state.chooseRune)
  const chooseShrineStore = useGameStore((state) => state.chooseShrine)
