import type { CSSProperties } from 'react'

export type EncounterBannerKind = 'start' | 'clear'

export interface EncounterBannerViewModel {
  readonly id: string
  readonly kind: EncounterBannerKind
  readonly chamber: number
  readonly title: string
  readonly subtitle: string
  readonly boss?: boolean
  readonly badges?: readonly string[]
}

export interface EncounterBannerProps {
  readonly cue: EncounterBannerViewModel
  readonly durationMs: number
}

export function EncounterBanner({ cue, durationMs }: EncounterBannerProps) {
  const eyebrow =
    cue.kind === 'clear'
      ? 'CHAMBER CLEAR'
      : cue.boss
        ? 'FINAL CHAMBER · BOSS'
        : `CHAMBER ${String(Math.max(1, cue.chamber)).padStart(2, '0')}`
  const style = {
    '--boda-encounter-duration': `${Math.max(240, durationMs)}ms`,
  } as CSSProperties

  return (
    <section
      key={cue.id}
      className="boda-encounter-banner"
      data-kind={cue.kind}
      data-testid="encounter-banner"
      role="status"
      aria-live="polite"
      aria-atomic="true"
      style={style}
    >
      <span className="boda-encounter-banner__flare" aria-hidden="true" />
      <div className="boda-encounter-banner__frame">
        <span className="boda-encounter-banner__wing" aria-hidden="true" />
        <div className="boda-encounter-banner__copy">
          <small>{eyebrow}</small>
          <strong>{cue.title}</strong>
          <span>{cue.subtitle}</span>
        </div>
        <span className="boda-encounter-banner__wing" aria-hidden="true" />
      </div>
      {cue.badges && cue.badges.length > 0 ? (
        <ul aria-label="챔버 특성">
          {cue.badges.map((badge) => (
            <li key={badge}>{badge}</li>
          ))}
        </ul>
      ) : null}
    </section>
  )
}
